DECLARE
  v_template_id uuid;
  v_version_id uuid;
BEGIN
  SELECT ft.id INTO v_template_id FROM public.form_templates ft WHERE ft.form_type = 'fit_and_proper' AND ft.service = 'declaration' LIMIT 1;
  SELECT fv.id INTO v_version_id FROM public.form_versions fv WHERE fv.template_id = v_template_id ORDER BY fv.version DESC LIMIT 1;

  IF v_template_id IS NULL OR v_version_id IS NULL THEN
    RAISE EXCEPTION 'Fit and Proper Declaration form not found (service=declaration) — run the form-creation migration first.';
  END IF;

